/** The reading figures of a post: minutes to read, views and likes, each with its glyph. */
import { type ReactNode } from "react";
import { Group } from "../primitives/group/group";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Text } from "../primitives/text/text";
import { tpl } from "../utils";
import type { Post } from "../blocks/post-card.types";
import type { PostExtras, PostSplitLabels } from "../blocks/post-split.types";

export type PostStatsProps = {
  post: Post;
  extras: PostExtras;
  labels: PostSplitLabels;
  align?: "start" | "center";
};

export function PostStats({ post, extras, labels, align = "start" }: PostStatsProps) {
  return (
    <Group
      gap="4"
      align="center"
      justify={align}
      className="flex-wrap text-muted-foreground"
      data-testid="post-stats"
    >
      <Group gap="2" align="center">
        <LucideIcon name="clock" size={16} />
        <Text size="sm">
          {tpl(labels.minutes, post.minutes)}
        </Text>
      </Group>
      <Group gap="2" align="center">
        <LucideIcon name="eye" size={16} />
        <Text size="sm">
          {tpl(labels.views, extras.views)}
        </Text>
      </Group>
      <Group gap="2" align="center">
        <LucideIcon name="heart" size={16} />
        <Text size="sm">
          {tpl(labels.likes, extras.likes)}
        </Text>
      </Group>
    </Group>
  );
}
